frappe.ui.form.on('Digital Economy Index Set', {
    onload: async function(frm) {
        if (!frm.is_new()) return; // Exit early if not a new form

        // Populate child tables on load
        await populateChildTables(frm);
    },

    // Handle changes to the rut_gon field
    rut_gon: async function(frm) {
        // Repopulate child tables when rut_gon changes
        await populateChildTables(frm);
    }
});

// Centralized function to populate child tables based on rut_gon
async function populateChildTables(frm) {
    // Configuration for child tables and mappings
    const TABLE_CONFIG = {
        tablesToClear: [
            "bang_nhan_thuc_so_va_the_che_so",
            "bang_ha_tang_va_an_ninh_mang",
            "bang_nhan_luc_so",
            "bang_hoat_dong_kinh_te_so",
            "bang_kts_logistics",
            "bang_doanh_thu_nganh_kts",
            "bang_kts_nganh_mui_nhon"
        ],
        chiSoMapping: [
            { bo_chi_so: "Nhận thức số và thể chế số", table: "bang_nhan_thuc_so_va_the_che_so" },
            { bo_chi_so: "Hạ tầng số và an ninh mạng", table: "bang_ha_tang_va_an_ninh_mang" },
            { bo_chi_so: "Nhân lực số", table: "bang_nhan_luc_so" },
            { bo_chi_so: "Hoạt động Kinh tế số", table: "bang_hoat_dong_kinh_te_so" },
            { bo_chi_so: "Kinh tế số Logistics", table: "bang_kts_logistics" },
            { bo_chi_so: "Doanh thu các ngành KTS", table: "bang_doanh_thu_nganh_kts" }
        ],
        staticRows: {
            table: "bang_kts_nganh_mui_nhon",
            data: [
                "Phần cứng, thiết bị và linh kiện điện tử, quang học",
                "H. Vận tải kho bãi",
                "I. Dịch vụ lưu trú và ăn uống"
            ]
        }
    };

    // Clear all specified child tables
    TABLE_CONFIG.tablesToClear.forEach(table => frm.clear_table(table));

    // Fetch and populate dynamic data for child tables
    const fetchAndAddToTable = async (bo_chi_so, table) => {
        try {
            const filters = { bo_chi_so: bo_chi_so };
            // Apply rut_gon filter only if rut_gon is checked (1) on Digital Economy Index Set
            if (frm.doc.rut_gon === 1) {
                filters.rut_gon = 1;
            }
            console.log(`Fetching Index Name for bo_chi_so: ${bo_chi_so} with filters:`, filters); // Debug log

            const response = await frappe.call({
                method: "frappe.client.get_list",
                args: {
                    doctype: "Index Name",
                    filters: filters,
                    fields: ["ten_chi_so", "so_thu_tu"],
                    order_by: "so_thu_tu asc",
                    limit_page_length: 0 // Fetch all records (no limit)
                }
            });
            const index_list = response.message || [];
            console.log(`Fetched ${index_list.length} records for ${bo_chi_so}:`, index_list); // Debug log

            index_list.forEach(record => {
                frm.add_child(table, { ten_chi_so: record.ten_chi_so });
            });
            frm.refresh_field(table);
        } catch (error) {
            frappe.msgprint({
                title: __("Error"),
                indicator: "red",
                message: __("Failed to load data for {0}: {1}", [bo_chi_so, error.message])
            });
        }
    };

    // Populate static data
    const populateStaticRows = () => {
        TABLE_CONFIG.staticRows.data.forEach(row_data => {
            frm.add_child(TABLE_CONFIG.staticRows.table, { nganh_kinh_te: row_data });
        });
        frm.refresh_field(TABLE_CONFIG.staticRows.table);
    };

    // Execute all operations
    try {
        await Promise.all(TABLE_CONFIG.chiSoMapping.map(mapping =>
            fetchAndAddToTable(mapping.bo_chi_so, mapping.table)
        ));
        populateStaticRows();
    } catch (error) {
        console.error("Error in populateChildTables:", error);
    }
}

frappe.ui.form.on('GSO Input', {
    // 1. Populate child tables on form load for new documents
    onload: async function(frm) {
        if (!frm.is_new()) return; // Exit early if not a new form

        // Configuration for API calls and table mappings
        const FETCH_CONFIG = {
            gso_input_index_table: {
                doctype: 'Index Name',
                field: 'name',
                targetField: 'ten_chi_so'
            },
            gso_input_sub_index_table: {
                doctype: 'Sub-Index Name',
                field: 'ten_chi_so_thanh_phan',
                targetField: 'ten_chi_so'
            }
        };
        const DATA_SOURCE = 'Cục thống kê';

        // Reusable function to fetch and populate a table
        const fetchAndPopulateTable = async (tableName, config) => {
            try {
                let filters = { nguon_du_lieu: DATA_SOURCE };

                // Add rut_gon filter only for Index Name doctype
                if (config.doctype === 'Index Name') {
                    filters.rut_gon = 1; // Fetch only records where rut_gon is checked
                }

                const response = await frappe.call({
                    method: 'frappe.client.get_list',
                    args: {
                        doctype: config.doctype,
                        filters: filters,
                        fields: [config.field]
                    }
                });

                const data = response.message || [];
                frm.clear_table(tableName);
                data.forEach(row => {
                    frm.add_child(tableName, {
                        [config.targetField]: row[config.field],
                        nguon_du_lieu: DATA_SOURCE
                    });
                });
                frm.refresh_field(tableName);
            } catch (error) {
                frappe.msgprint({
                    title: __('Error'),
                    indicator: 'red',
                    message: __('Failed to load data for {0}: {1}', [config.doctype, error.message])
                });
                throw error; // Re-throw to allow Promise.all to handle rejection
            }
        };

        // Execute fetches in parallel
        try {
            await Promise.all(
                Object.entries(FETCH_CONFIG).map(([tableName, config]) =>
                    fetchAndPopulateTable(tableName, config)
                )
            );
        } catch (error) {
            console.error('Error in onload handler:', error);
        }
    },

    // 2. Apply UI restrictions for non-Admin users
    refresh: function(frm) {
        if (frappe.session.user === "Administrator") return;

        const TABLE_NAMES = ['gso_input_index_table', 'gso_input_sub_index_table'];

        TABLE_NAMES.forEach(tableName => {
            const grid = frm.fields_dict[tableName]?.grid;
            if (!grid) {
                console.warn(`Grid for table ${tableName} not found`);
                return;
            }

            // Disable drag-and-drop
            frm.page.body
                .find(`[data-fieldname="${tableName}"] .data-row .sortable-handle`)
                .removeClass('sortable-handle');

            // Configuration for elements to hide/disable
            const uiRestrictions = [
                { selector: '.grid-add-row', action: 'hide' },
                { selector: '.grid-remove-rows', action: 'hide' },
                { selector: '.grid-remove-all-rows', action: 'hide' },
                { selector: '.grid-delete-row', action: 'hide' },
                { selector: '.grid-insert-row-below', action: 'hide' },
                { selector: '.grid-insert-row', action: 'hide' },
                { selector: '.grid-duplicate-row', action: 'hide' },
                { selector: '.grid-move-row', action: 'hide' },
                { selector: '.grid-append-row', action: 'hide' },
                { selector: 'div.d-flex', action: 'css', style: { visibility: 'hidden' } },
                { selector: '.btn-open-row', action: 'hide' }
            ];

            // Apply restrictions to grid wrapper
            const $wrapper = grid.wrapper;
            uiRestrictions.forEach(restriction => {
                if (restriction.action === 'hide') {
                    $wrapper.find(restriction.selector).hide();
                } else if (restriction.action === 'css') {
                    $wrapper.find(restriction.selector).css(restriction.style);
                }
            });

            // Disable and hide grid buttons
            const $gridButtons = grid.grid_buttons.find('.btn');
            $gridButtons.prop('disabled', true);
            $gridButtons.hide();

            // Lock grid interactions
            grid.cannot_add_rows = true;
            grid.cannot_delete_rows = true;
        });

        // Hide sidebar elements
        $('.btn-reset.sidebar-toggle-btn').hide();
        $('.col-lg-2.layout-side-section').hide();
    },

    // 3. Calculate completion percentage before saving
    before_save: function(frm) {
        let tables = ['gso_input_index_table', 'gso_input_sub_index_table'];
        let total_rows = 0;
        let filled_rows = 0;

        tables.forEach(table => {
            if (frm.doc[table]) {
                total_rows += frm.doc[table].length;
                frm.doc[table].forEach(row => {
                    if (row.gia_tri && row.gia_tri != 0) {
                        filled_rows++;
                    }
                });
            }
        });

        let completion_percentage = total_rows > 0 ? (filled_rows / total_rows) * 100 : 0;
        frm.set_value('hoan_thanh', completion_percentage.toFixed(2));
    },

    // Additional event handlers (if needed)
    gso_input_sub_index_table_on_form_rendered: function(frm, cdt, cdn) {
        if (frappe.session.user !== "Administrator") {
            applyUserRestrictions(frm);
        }
    },
    gso_input_index_table_on_form_rendered: function(frm, cdt, cdn) {
        if (frappe.session.user !== "Administrator") {
            applyUserRestrictions(frm);
        }
    }
});

