function calculateTotalGRDP(frm) {
    try {
        // Calculate the sum of grdp_uoc_tinh from all rows
        const totalGRDP = (frm.doc.bang_uoc_tinh || []).reduce((sum, row) => {
            return sum + (row.grdp_uoc_tinh || 0);
        }, 0);

        // Add thue_san_pham_tru_tro_cap_san_pham to the total
        const thueValue = frm.doc.thue_san_pham_tru_tro_cap_san_pham || 0;
        const finalTotal = totalGRDP + thueValue;

        // Set the total with 2 decimal places to avoid floating-point precision issues
        frm.set_value('tong_grdp_uoc_tinh', parseFloat(finalTotal.toFixed(2)));
        frm.refresh_field('tong_grdp_uoc_tinh');
    } catch (error) {
        frappe.msgprint({
            title: __('Error'),
            indicator: 'red',
            message: __('Failed to calculate Tổng GRDP ước tính: {0}', [error.message])
        });
        console.error('Error in calculateTotalGRDP:', error);
    }
}

