// Helper Functions

// Find and populate bang_va_ict child table from Estimated GRDP
function findRecord(frm) {
    const { quy, nam, du_lieu_nam } = frm.doc;
    const namTruoc = nam ? nam - 1 : null;

    // Clear previous data if prerequisites are not met
    if (!nam || (du_lieu_nam === 0 && !quy)) {
        frm.set_value('chi_so_grdp_uoc_tinh', '');
        frm.clear_table('bang_va_ict');
        frm.refresh_field('bang_va_ict');
        return;
    }

    // Prepare filters based on du_lieu_nam
    const filters = du_lieu_nam
        ? { nam: namTruoc, du_lieu_nam: 1 } // For yearly data
        : { quy: quy, nam: namTruoc }; // For quarterly data

    // Fetch Estimated GRDP records
    frappe.call({
        method: 'frappe.client.get_list',
        args: {
            doctype: 'Estimated GRDP',
            filters: filters,
            fields: ['name'],
            limit_page_length: 1 // Expect only one matching record
        },
        callback: function(r) {
            try {
                const records = r.message || [];
                if (records.length > 0) {
                    const estimatedGrdp = records[0];
                    frm.set_value('chi_so_grdp_uoc_tinh', estimatedGrdp.name);

                    // Fetch detailed record to populate child table
                    frappe.call({
                        method: 'frappe.client.get',
                        args: {
                            doctype: 'Estimated GRDP',
                            name: estimatedGrdp.name
                        },
                        callback: function(r) {
                            try {
                                const doc = r.message;
                                if (doc && doc.bang_uoc_tinh) {
                                    frm.clear_table('bang_va_ict');
                                    doc.bang_uoc_tinh.forEach(row => {
                                        frm.add_child('bang_va_ict', {
                                            nganh_kinh_te: row.nganh_kinh_te,
                                            grdp_uoc_tinh: row.grdp_uoc_tinh
                                        });
                                    });
                                    frm.refresh_field('bang_va_ict');
                                } else {
                                    frm.set_value('chi_so_grdp_uoc_tinh', '');
                                    frm.clear_table('bang_va_ict');
                                    frm.refresh_field('bang_va_ict');
                                }
                            } catch (error) {
                                frappe.msgprint({
                                    title: __('Error'),
                                    indicator: 'red',
                                    message: __('Failed to fetch Estimated GRDP details: {0}', [error.message])
                                });
                                console.error('Error fetching Estimated GRDP details:', error);
                            }
                        }
                    });
                } else {
                    frm.set_value('chi_so_grdp_uoc_tinh', '');
                    frm.clear_table('bang_va_ict');
                    frm.refresh_field('bang_va_ict');
                }
            } catch (error) {
                frappe.msgprint({
                    title: __('Error'),
                    indicator: 'red',
                    message: __('Failed to find Estimated GRDP record: {0}', [error.message])
                });
                console.error('Error in findRecord:', error);
            }
        }
    });
}

// Calculate VA ICT for a single row
function calculateVaIct(frm, cdt, cdn) {
    const row = locals[cdt][cdn];

    // Update condition to handle 0 value for he_so_chuyen_doi
    if (row.ty_le_chi_tieu_ict_tieu_dung_trung_gian && row.grdp_uoc_tinh && frm.doc.he_so_chuyen_doi !== undefined) {
        const vaIct = row.grdp_uoc_tinh * row.ty_le_chi_tieu_ict_tieu_dung_trung_gian * frm.doc.he_so_chuyen_doi;
        frappe.model.set_value(cdt, cdn, 'va_ict', vaIct).then(() => {
            calculateTotalVaIct(frm);
        });
    } else {
        frappe.model.set_value(cdt, cdn, 'va_ict', 0).then(() => {
            calculateTotalVaIct(frm);
        });
    }
}

// Calculate total VA ICT across all rows
function calculateTotalVaIct(frm) {
    const tongVaIct = (frm.doc.bang_va_ict || []).reduce((total, row) => {
        return total + (row.va_ict || 0);
    }, 0);

    if (frm.doc.tong_va !== tongVaIct) {
        frm.set_value('tong_va', tongVaIct);
    }
}

