// Fetch VA ICT data and populate bang_va_ict child table
function fetchVaIctTable(frm, quy, nam, du_lieu_nam) {
    const filters = { nam: nam, du_lieu_nam: du_lieu_nam };
    if (!du_lieu_nam && quy) {
        filters.quy = quy;
    }

    fetchAndPopulateTable(frm, {
        doctype: 'VA ICT',
        filters: filters,
        linkField: 'du_lieu_va_ict',
        childTable: 'bang_va_ict',
        childTableSource: 'bang_va_ict',
        setTotalField: 'tong_va_ict', // Fetch tong_va_ict from VA ICT
        onSuccess: () => calculateAll(frm)
    });
}

// Generic function to fetch data and populate a child table
function fetchAndPopulateTable(frm, options) {
    const { doctype, filters, linkField, childTable, childTableSource, setTotalField, onSuccess } = options;

    frappe.call({
        method: 'frappe.client.get_list',
        args: {
            doctype: doctype,
            filters: filters,
            fields: ['name'],
            limit_page_length: 1 // Expect only one matching record
        },
        callback: function(r) {
            try {
                const records = r.message || [];
                if (records.length > 0) {
                    const record = records[0];
                    frm.set_value(linkField, record.name);

                    frappe.call({
                        method: 'frappe.client.get',
                        args: {
                            doctype: doctype,
                            name: record.name
                        },
                        callback: function(r) {
                            try {
                                const doc = r.message;
                                if (doc) {
                                    // Set total field if specified (e.g., tong_va_ict for VA ICT, tong_grdp_uoc_tinh for Estimated GRDP)
                                    if (setTotalField && doc[setTotalField] !== undefined) {
                                        console.log(`Setting ${setTotalField} to ${doc[setTotalField]}`); // Debug log
                                        frm.set_value(setTotalField, doc[setTotalField]);
                                    } else if (setTotalField) {
                                        console.log(`Field ${setTotalField} not found in ${doctype}`); // Debug log
                                    }

                                    // Populate child table
                                    const childRows = doc[childTableSource] || [];
                                    console.log(`Populating ${childTable} with ${childRows.length} rows`); // Debug log
                                    frm.clear_table(childTable);
                                    childRows.forEach(row => {
                                        frm.add_child(childTable, { ...row });
                                    });
                                    frm.refresh_field(childTable);

                                    if (onSuccess) {
                                        onSuccess();
                                    }
                                } else {
                                    clearTableData(frm, linkField, childTable, setTotalField);
                                    if (onSuccess) {
                                        onSuccess();
                                    }
                                }
                            } catch (error) {
                                frappe.msgprint({
                                    title: __('Error'),
                                    indicator: 'red',
                                    message: __('Failed to fetch {0} details: {1}', [doctype, error.message])
                                });
                                console.error(`Error fetching ${doctype} details:`, error);
                            }
                        }
                    });
                } else {
                    console.log(`No ${doctype} records found for filters:`, filters); // Debug log
                    clearTableData(frm, linkField, childTable, setTotalField);
                    if (onSuccess) {
                        onSuccess();
                    }
                }
            } catch (error) {
                frappe.msgprint({
                    title: __('Error'),
                    indicator: 'red',
                    message: __('Failed to find {0} record: {1}', [doctype, error.message])
                });
                console.error(`Error in fetchAndPopulateTable for ${doctype}:`, error);
            }
        }
    });
}

// Clear link field, child table, and optional total field
function clearTableData(frm, linkField, childTable, setTotalField) {
    frm.set_value(linkField, null);
    if (setTotalField) {
        frm.set_value(setTotalField, null);
    }
    frm.clear_table(childTable);
    frm.refresh_field(childTable);
}

// Clear all form data when prerequisites are not met
function clearFormData(frm) {
    clearTableData(frm, 'du_lieu_uoc_tinh', 'bang_grdp_uoc_tinh', 'tong_grdp_uoc_tinh');
    clearTableData(frm, 'du_lieu_va_ict', 'bang_va_ict', 'tong_va_ict');
    calculateAll(frm);
}

// Perform all calculations in sequence
function calculateAll(frm) {
    calculateCoreKts(frm); // Calculate KTS lõi (Core Digital Economy)
    calculateRippleKts(frm); // Calculate KTS lan tỏa (Ripple Digital Economy)
    calculateTotalKts(frm); // Calculate KTS tổng (Total Digital Economy)
    calculateCoreKtsRatio(frm); // Calculate Tỷ trọng KTS lõi (Core KTS Ratio)
    calculateRippleKtsRatio(frm); // Calculate Tỷ trọng KTS lan tỏa (Ripple KTS Ratio)
    calculateTotalKtsRatio(frm); // Calculate Tỷ trọng KTS tổng (Total KTS Ratio)
    calculateKtsLogisticsRatio(frm); // Calculate Tỷ trọng KTS Logistics
}

// Calculate KTS lõi (Core Digital Economy)
function calculateCoreKts(frm) {
    const totalKtsLoi = (frm.doc.bang_grdp_uoc_tinh || []).reduce((sum, row) => {
        const isCoreKts = row.loai_kts === 'KTS lõi';
        console.log(`Row: ${row.nganh_kinh_te}, loai_kts: ${row.loai_kts}, grdp_uoc_tinh: ${row.grdp_uoc_tinh}, isCoreKts: ${isCoreKts}`); // Debug log
        return isCoreKts ? sum + (row.grdp_uoc_tinh || 0) : sum;
    }, 0);
    console.log(`Total KTS lõi: ${totalKtsLoi}`); // Debug log
    frm.set_value('kts_loi', totalKtsLoi > 0 ? totalKtsLoi : null);
}

// Calculate KTS lan tỏa (Ripple Digital Economy)
function calculateRippleKts(frm) {
    const totalKtsLoi = (frm.doc.bang_va_ict || []).reduce((sum, row) => {
        const isCoreKts = row.loai_kts === 'KTS lõi';
        console.log(`Row: ${row.nganh_kinh_te}, loai_kts: ${row.loai_kts}, va_ict: ${row.va_ict}, isCoreKts: ${isCoreKts}`); // Debug log
        return isCoreKts ? sum + (row.va_ict || 0) : sum;
    }, 0);
    const tongVa = frm.doc.tong_va_ict || 0;
    const ktsLanToa = tongVa - totalKtsLoi;
    console.log(`tong_va_ict: ${tongVa}, totalKtsLoi: ${totalKtsLoi}, kts_lan_toa: ${ktsLanToa}`); // Debug log
    frm.set_value('kts_lan_toa', ktsLanToa > 0 ? ktsLanToa : null);
}

// Calculate KTS tổng (Total Digital Economy)
function calculateTotalKts(frm) {
    const ktsLoi = frm.doc.kts_loi || 0;
    const ktsLanToa = frm.doc.kts_lan_toa || 0;
    if (ktsLoi > 0 && ktsLanToa > 0) {
        const ktsTong = ktsLoi + ktsLanToa;
        console.log(`kts_loi: ${ktsLoi}, kts_lan_toa: ${ktsLanToa}, kts_tong: ${ktsTong}`); // Debug log
        frm.set_value('kts_tong', ktsTong);
    } else {
        console.log(`kts_tong not calculated: kts_loi: ${ktsLoi}, kts_lan_toa: ${ktsLanToa}`); // Debug log
        frm.set_value('kts_tong', null);
    }
}

// Calculate Tỷ trọng KTS lõi (Core KTS Ratio)
function calculateCoreKtsRatio(frm) {
    const ktsLoi = frm.doc.kts_loi || 0;
    const tongGrdp = frm.doc.tong_grdp_uoc_tinh || 0;
    if (ktsLoi > 0 && tongGrdp > 0) {
        const ratio = (ktsLoi / tongGrdp) * 100;
        console.log(`kts_loi: ${ktsLoi}, tong_grdp_uoc_tinh: ${tongGrdp}, ty_trong_kts_loi: ${ratio}`); // Debug log
        frm.set_value('ty_trong_kts_loi', parseFloat(ratio.toFixed(2)));
    } else {
        console.log(`ty_trong_kts_loi not calculated: kts_loi: ${ktsLoi}, tong_grdp_uoc_tinh: ${tongGrdp}`); // Debug log
        frm.set_value('ty_trong_kts_loi', null);
    }
}

// Calculate Tỷ trọng KTS lan tỏa (Ripple KTS Ratio)
function calculateRippleKtsRatio(frm) {
    const ktsLanToa = frm.doc.kts_lan_toa || 0;
    const tongGrdp = frm.doc.tong_grdp_uoc_tinh || 0;
    if (ktsLanToa > 0 && tongGrdp > 0) {
        const ratio = (ktsLanToa / tongGrdp) * 100;
        console.log(`kts_lan_toa: ${ktsLanToa}, tong_grdp_uoc_tinh: ${tongGrdp}, ty_trong_kts_lan_toa: ${ratio}`); // Debug log
        frm.set_value('ty_trong_kts_lan_toa', parseFloat(ratio.toFixed(2)));
    } else {
        console.log(`ty_trong_kts_lan_toa not calculated: kts_lan_toa: ${ktsLanToa}, tong_grdp_uoc_tinh: ${tongGrdp}`); // Debug log
        frm.set_value('ty_trong_kts_lan_toa', null);
    }
}

// Calculate Tỷ trọng KTS tổng (Total KTS Ratio)
function calculateTotalKtsRatio(frm) {
    const tyTrongKtsLoi = frm.doc.ty_trong_kts_loi || 0;
    const tyTrongKtsLanToa = frm.doc.ty_trong_kts_lan_toa || 0;
    if (tyTrongKtsLoi > 0 && tyTrongKtsLanToa > 0) {
        const totalRatio = tyTrongKtsLoi + tyTrongKtsLanToa;
        console.log(`ty_trong_kts_loi: ${tyTrongKtsLoi}, ty_trong_kts_lan_toa: ${tyTrongKtsLanToa}, ty_trong_kts_tong: ${totalRatio}`); // Debug log
        frm.set_value('ty_trong_kts_tong', parseFloat(totalRatio.toFixed(2)));
    } else {
        console.log(`ty_trong_kts_tong not calculated: ty_trong_kts_loi: ${tyTrongKtsLoi}, ty_trong_kts_lan_toa: ${tyTrongKtsLanToa}`); // Debug log
        frm.set_value('ty_trong_kts_tong', null);
    }
}

// Calculate Tỷ trọng KTS Logistics
function calculateKtsLogisticsRatio(frm) {
    const grdpVanTaiKhoBai = (frm.doc.bang_grdp_uoc_tinh || []).find(row => row.nganh_kinh_te === 'H. Vận tải kho bãi');
    const vaIctVanTaiKhoBai = (frm.doc.bang_va_ict || []).find(row => row.nganh_kinh_te === 'H. Vận tải kho bãi');

    if (grdpVanTaiKhoBai && vaIctVanTaiKhoBai && (grdpVanTaiKhoBai.grdp_uoc_tinh || 0) > 0) {
        const ratio = ((vaIctVanTaiKhoBai.va_ict || 0) / grdpVanTaiKhoBai.grdp_uoc_tinh) * 100;
        console.log(`va_ict: ${vaIctVanTaiKhoBai.va_ict}, grdp_uoc_tinh: ${grdpVanTaiKhoBai.grdp_uoc_tinh}, ty_trong_kts_logistics: ${ratio}`); // Debug log
        frm.set_value('ty_trong_kts_logistics', parseFloat(ratio.toFixed(2)));
    } else {
        console.log(`ty_trong_kts_logistics not calculated: grdpVanTaiKhoBai: ${JSON.stringify(grdpVanTaiKhoBai)}, vaIctVanTaiKhoBai: ${JSON.stringify(vaIctVanTaiKhoBai)}`); // Debug log
        frm.set_value('ty_trong_kts_logistics', null);
    }
}

