// TÍNH ĐIỂM CHUẨN HÓA Ở CÁC BẢNG CON
function calculate_diem_chuan_hoa(frm, cdt, cdn) {
    let d = locals[cdt][cdn];
    let muc_tieu_tham_chieu = parseFloat(d.muc_tieu_tham_chieu) || 0;
    let diem_co_so = parseFloat(d.diem_co_so) || 0;
    let gia_tri_tham_chieu = parseFloat(d.gia_tri_tham_chieu) || 0;

    if (muc_tieu_tham_chieu > 0 && gia_tri_tham_chieu >= 0) {
        d.diem_chuan_hoa = (gia_tri_tham_chieu >= muc_tieu_tham_chieu)
            ? diem_co_so
            : (gia_tri_tham_chieu / muc_tieu_tham_chieu) * diem_co_so;
    } else {
        d.diem_chuan_hoa = 0;
    }
    refresh_child_tables(frm);
}

// TÍNH TỔNG ĐIỂM CƠ SỞ VÀ ĐIỂM CHUẨN HÓA
function calculate_all_totals(frm) {
    calculate_total_for_tables(frm, "diem_co_so", {
        "bang_nhan_thuc_so_va_the_che_so": "tong_diem_co_so_bang_nhan_thuc_so_va_the_che_so",
        "bang_ha_tang_va_an_ninh_mang": "tong_diem_co_so_ha_tang_va_an_ninh_mang",
        "bang_nhan_luc_so": "tong_diem_co_so_nhan_luc_so",
        "bang_hoat_dong_kinh_te_so": "tong_diem_co_so_hoat_dong_kinh_te_so",
        "bang_kts_logistics": "tong_diem_co_so_kts_logistics"
    });

    calculate_total_for_tables(frm, "diem_chuan_hoa", {
        "bang_nhan_thuc_so_va_the_che_so": "tong_diem_nhan_thuc_so_va_the_che_so",
        "bang_ha_tang_va_an_ninh_mang": "tong_diem_ha_tang_va_an_ninh_mang",
        "bang_nhan_luc_so": "tong_diem_nhan_luc_so",
        "bang_hoat_dong_kinh_te_so": "tong_diem_hoat_dong_kinh_te_so",
        "bang_kts_logistics": "tong_diem_kts_logistics"
    });
}

// TÍNH TỔNG DÙNG CHUNG
function calculate_total_for_tables(frm, field, table_to_total_map) {
    Object.keys(table_to_total_map).forEach(table => {
        let total = 0;

        if (frm.doc[table]) {
            frm.doc[table].forEach(row => {
                total += parseFloat(row[field]) || 0;
            });
        }

        console.log(`Calculating ${table_to_total_map[table]} for ${table}: ${total}`); // Debug log
        frm.set_value(table_to_total_map[table], total);
    });
}

function calculate_gia_tri_tham_chieu(frm, cdt, cdn) {
    let d = locals[cdt][cdn];
    let gia_tri_a = parseFloat(d.gia_tri_thanh_phan_a) || 0;
    let gia_tri_b = parseFloat(d.gia_tri_thanh_phan_b) || 0;
    if (gia_tri_b !== 0) {
        d.gia_tri_tham_chieu = (gia_tri_a / gia_tri_b) * 100;
    } else {
        d.gia_tri_tham_chieu = 0;
    }
    refresh_child_tables(frm);
}

