function fetch_data_from_grdp_index(frm, doctype, thoi_gian_field, target_table) {
    frappe.call({
        method: "frappe.client.get_list",
        args: {
            doctype: doctype,
            filters: { [thoi_gian_field]: frm.doc[thoi_gian_field] },
            fields: ["name"]
        },
        callback: function(r) {
            if (!r.message.length) {
                return frappe.msgprint(__('Dữ liệu chưa được nhập cho ' + frm.doc.quy + '/' + frm.doc.nam));
            }
            fetch_and_process_grdp_data(frm, doctype, r.message[0].name, target_table);
        }
    });
}

function fetch_and_process_grdp_data(frm, doctype, name, target_table) {
    frappe.call({
        method: "frappe.client.get",
        args: { doctype: doctype, name: name },
        callback: function(r) {
            if (!r.message) {
                return;
            }

            const doc = r.message;
            const updates = process_grdp_data(frm, doc, target_table);
            display_grdp_update_confirmation(frm, updates, target_table);
        }
    });
}

function process_grdp_data(frm, doc, target_table) {
    const updates = [];

    frm.doc[target_table].forEach(item => {
        updates.push({
            nganh_kinh_te: item.nganh_kinh_te,
            gia_tri_grdp_thanh_pho: doc.tong_grdp_uoc_tinh || "chưa có dữ liệu",
            va_kts_tong: doc.tong_va_ict || "chưa có dữ liệu",
            gia_tri_va: "chưa có dữ liệu",
            va_kts_nganh: "chưa có dữ liệu"
        });
    });

    doc.bang_grdp_uoc_tinh.forEach(grdp_row => {
        const update = updates.find(u => u.nganh_kinh_te === grdp_row.nganh_kinh_te);
        if (update) {
            update.gia_tri_va = grdp_row.grdp_uoc_tinh || "chưa có dữ liệu";
        }
    });

    doc.bang_va_ict.forEach(va_row => {
        const update = updates.find(u => u.nganh_kinh_te === va_row.nganh_kinh_te);
        if (update) {
            update.va_kts_nganh = va_row.va_ict || "chưa có dữ liệu";
        }
    });

    updates.forEach(update => {
        calculate_ratios(frm, "bang_kts_nganh_mui_nhon", update);
    });

    return updates;
}

