            style: 'currency',
            currency: 'VND',
        }).format(value);
    }

    let dialog = new frappe.ui.Dialog({
        title: __('Ngành mũi nhọn'),
        fields: [
            {
                fieldtype: 'HTML',
                fieldname: 'table_html',
                options: `
                    <div>
                        <div>
                            <p>${__('Giá trị GRDP thành phố')}: <b>${formatCurrency(updates[0].gia_tri_grdp_thanh_pho || 'Chưa có dữ liệu')}</b></p>
                        </div>
                        <div>
                            <p>${__('VA KTS Tổng')}: <b>${formatCurrency(updates[0].va_kts_tong || 'Chưa có dữ liệu')}</b></p>
                        </div>
                    </div>
                    <table class="table table-bordered">
                        <thead>
                            <tr>
                                <th>${__('Ngành kinh tế')}</th>
                                <th>${__('Giá trị VA')}</th>
                                <th>${__('VA KTS của ngành')}</th>
                            </tr>
                        </thead>
                        <tbody>
                            ${updates.map(update => `
                                <tr>
                                    <td>${update.nganh_kinh_te}</td>
                                    <td>${formatCurrency(update.gia_tri_va || 'Chưa có dữ liệu')}</td>
                                    <td>${formatCurrency(update.va_kts_nganh || 'Chưa có dữ liệu')}</td>
                                </tr>
                            `).join('')}
                        </tbody>
                    </table>`
            }
        ],
        primary_action_label: __('Cập nhật'),
        primary_action: function() {
            updates.forEach(update => {
                frm.doc[target_table].forEach(item => {
                    if (item.nganh_kinh_te === update.nganh_kinh_te) {
                        item.gia_tri_grdp_thanh_pho = update.gia_tri_grdp_thanh_pho || "Chưa có dữ liệu";
                        item.va_kts_tong = update.va_kts_tong || "Chưa có dữ liệu";
                        item.gia_tri_va = update.gia_tri_va || "Chưa có dữ liệu";
                        item.va_kts_nganh = update.va_kts_nganh || "Chưa có dữ liệu";
                        calculate_ratios(frm, target_table, item);
                    }
                });
            });
            frm.dirty();
            frm.refresh_field(target_table);
            frappe.show_alert({
                message: __('Dữ liệu đã được cập nhật thành công!'),
                indicator: 'green'
            }, 5);

            dialog.hide();
        },
        secondary_action_label: __('Hủy'),
        secondary_action: function() {
            dialog.hide();
        }
    });
    dialog.show();
    updates.forEach(update => {
        frm.doc[target_table].forEach(item => {
            if (item.nganh_kinh_te === update.nganh_kinh_te) {
                calculate_ratios(frm, target_table, item);
            }
        });
    });
}

function calculate_ratios(frm, cdt, row) {
    if (row.gia_tri_va && row.gia_tri_grdp_thanh_pho) {
        row.ty_trong_va_grdp = (flt(row.gia_tri_va) / flt(row.gia_tri_grdp_thanh_pho)) * 100;
    } else {
        row.ty_trong_va_grdp = 0;
    }

    if (row.va_kts_nganh && row.gia_tri_va) {
        row.ty_trong_va_kts_nganh_va_nganh = (flt(row.va_kts_nganh) / flt(row.gia_tri_va)) * 100;
    } else {
        row.ty_trong_va_kts_nganh_va_nganh = 0;
    }

    if (row.va_kts_nganh && row.va_kts_tong) {
        row.ty_trong_va_kts_nganh_va_kts_tong = (flt(row.va_kts_nganh) / flt(row.va_kts_tong)) * 100;
    } else {
        row.ty_trong_va_kts_nganh_va_kts_tong = 0;
    }
    frm.refresh_field('bang_kts_nganh_mui_nhon');
}

function fetch_data(frm, doctype, source_name, index_table_name, sub_index_table_name) {
    frappe.call({
        method: "frappe.client.get_list",
        args: {
            doctype: doctype,
            filters: { thoi_gian: frm.doc.thoi_gian },
            fields: ["name"]
        },
        callback: function(r) {
            if (!r.message.length) {
                return frappe.msgprint(__('Dữ liệu chưa được nhập bởi ' + source_name));
            }
            fetch_and_process_data(frm, doctype, r.message[0].name, index_table_name, sub_index_table_name, source_name);
        }
    });
}

function fetch_and_process_data(frm, doctype, name, index_table_name, sub_index_table_name, source_name) {
    frappe.call({
        method: "frappe.client.get",
        args: { doctype: doctype, name: name },
        callback: function(r) {
            if (!r.message) {
                return;
            }
            const doc = r.message;
            const modifiedDate = formatDate(doc.modified); // Added modified
            const { updates: updates_main, missing_values: missing_values_main } = process_index_table(doc[index_table_name]);
            const { updates: updates_sub, missing_values: missing_values_sub } = process_sub_index_table(frm, doc[sub_index_table_name]);
            display_update_confirmation(frm, updates_main, missing_values_main, updates_sub, missing_values_sub, source_name, modifiedDate);
        }
    });
}

function formatDate(dateString) {
    const date = new Date(dateString);
    const hours = String(date.getHours()).padStart(2, '0');
    const minutes = String(date.getMinutes()).padStart(2, '0');
    const day = String(date.getDate()).padStart(2, '0');
    const month = String(date.getMonth() + 1).padStart(2, '0'); // Months are zero-based
    const year = date.getFullYear();

    return `${hours}:${minutes} ${day}/${month}/${year}`;
}

function process_index_table(index_table) {
    const updates = [];
    const missing_values = [];
    index_table.forEach(row => {
        if (row.gia_tri != null) { // Include 0 as a valid value
            updates.push({
                ten_chi_so: row.ten_chi_so,
                gia_tri: row.gia_tri
            });
        } else {
            missing_values.push({
                ten_chi_so: row.ten_chi_so,
                gia_tri: "Chưa có dữ liệu"
            });
        }
    });
    return { updates, missing_values };
}

function process_sub_index_table(frm, sub_index_table) {
    const updates = [];
    const missing_values = [];
    const updatedChiSos = new Set(); // Keep track of updated chi so across all tables
    const tableNames = [
        'bang_nhan_thuc_so_va_the_che_so',
        'bang_ha_tang_va_an_ninh_mang',
        'bang_nhan_luc_so',
        'bang_hoat_dong_kinh_te_so',
        'bang_kts_logistics',
        'bang_doanh_thu_nganh_kts'
    ];

    sub_index_table.forEach(row => {
        if (row.gia_tri != null) { // Include 0 as a valid value
            // Check if this ten_chi_so has already been added to updates
            const updateKey = `${row.ten_chi_so}:${row.gia_tri}`; // Unique key based on ten_chi_so and gia_tri
            if (!updatedChiSos.has(updateKey)) {
                tableNames.forEach(tableName => {
                    frm.doc[tableName].forEach(item => {
                        if (item.chi_so_thanh_phan_a === row.ten_chi_so || item.chi_so_thanh_phan_b === row.ten_chi_so) {
                            updates.push({
                                table: tableName,
                                chi_so_thanh_phan: item.chi_so_thanh_phan_a === row.ten_chi_so ? 'a' : 'b',
                                ten_chi_so: row.ten_chi_so,
                                gia_tri: row.gia_tri
                            });
                            calculate_gia_tri_tham_chieu(frm, item, row.gia_tri);
                        }
                    });
                });
                updatedChiSos.add(updateKey); // Mark this ten_chi_so and gia_tri pair as processed
            }
        } else {
            const existingMissingValue = missing_values.find(m => m.ten_chi_so === row.ten_chi_so);
            if (!existingMissingValue) {
                missing_values.push({
                    ten_chi_so: row.ten_chi_so,
                    gia_tri: "Chưa có dữ liệu"
                });
            }
        }
    });

    // Remove duplicates from updates by keeping only the first occurrence of each ten_chi_so
    const uniqueUpdates = [];
    const seenChiSos = new Set();
    updates.forEach(update => {
        if (!seenChiSos.has(update.ten_chi_so)) {
            uniqueUpdates.push(update);
            seenChiSos.add(update.ten_chi_so);
        }
    });

    return { updates: uniqueUpdates, missing_values };
}

function display_update_confirmation(frm, updates_main, missing_values_main, updates_sub, missing_values_sub, source_name, source_modified) {
    let dialog = new frappe.ui.Dialog({
        title: __(`Dữ liệu cập nhật bởi ${source_name} lần cuối lúc ${source_modified}`),
        fields: [
            {
                fieldtype: 'HTML',
                fieldname: 'table_html',
                options: generateHtmlContent(updates_main, missing_values_main, updates_sub, missing_values_sub)
            }
        ],
        primary_action_label: __('Cập nhật'),
        primary_action: function() {
            updateValues(frm, updates_main, updates_sub);
            frm.dirty();
            refreshFields(frm);
            frappe.show_alert({
                message: __('Dữ liệu đã được cập nhật, hãy lưu lại bản ghi!'),
                indicator: 'green'
            }, 6);
            dialog.hide();
        },
        secondary_action_label: __('Hủy'),
        secondary_action: function() {
            dialog.hide();
        }
    });
    dialog.show();
}

function generateHtmlContent(updates_main, missing_values_main, updates_sub, missing_values_sub) {
    let message = "";

    // Chỉ số chính
    if (updates_main.length > 0 || missing_values_main.length > 0) {
        let total_main = updates_main.length + missing_values_main.length;
        let valid_main = updates_main.filter(update => update.gia_tri !== 0).length; // Count only non-zero values
        message += `<p><b>Chỉ số chính: ${valid_main}/${total_main}</b></p>`;
        message += "<table class='table table-bordered'>";
        message += "<thead><tr><th>Tên chỉ số</th><th>Giá trị</th></tr></thead><tbody>";
        updates_main.forEach(update => {
            message += `<tr><td>${update.ten_chi_so}</td><td>${update.gia_tri}</td></tr>`;
        });
        missing_values_main.forEach(missing => {
            message += `<tr><td>${missing.ten_chi_so}</td><td>${missing.gia_tri}</td></tr>`;
        });
        message += "</tbody></table>";
    }

    // Chỉ số thành phần
    if (updates_sub.length > 0 || missing_values_sub.length > 0) {
        let total_sub = updates_sub.length + missing_values_sub.length;
        let valid_sub = updates_sub.filter(update => update.gia_tri !== 0).length; // Count only non-zero values
        message += `<p><b>Chỉ số thành phần: ${valid_sub}/${total_sub}</b></p>`;
        message += "<table class='table table-bordered'>";
        message += "<thead><tr><th>Tên chỉ số</th><th>Giá trị</th></tr></thead><tbody>";
        updates_sub.forEach(update => {
            message += `<tr><td>${update.ten_chi_so}</td><td>${update.gia_tri}</td></tr>`;
        });
        missing_values_sub.forEach(missing => {
            message += `<tr><td>${missing.ten_chi_so}</td><td>${missing.gia_tri}</td></tr>`;
        });
        message += "</tbody></table>";
    }
    return message;
}

function updateValues(frm, updates_main, updates_sub) {

    updates_main.forEach(update => {
        const tables = [
            frm.doc.bang_nhan_thuc_so_va_the_che_so,
            frm.doc.bang_ha_tang_va_an_ninh_mang,
            frm.doc.bang_nhan_luc_so,
            frm.doc.bang_hoat_dong_kinh_te_so,
            frm.doc.bang_kts_logistics,
            frm.doc.bang_doanh_thu_nganh_kts
        ];

        tables.forEach(table => {
            table.forEach(item => {
                if (item.ten_chi_so === update.ten_chi_so) {
                    item.gia_tri_tham_chieu = update.gia_tri;
                    calculate_gia_tri_tham_chieu(frm, item);
                }
            });
        });
    });

    updates_sub.forEach(update => {
        const table = frm.doc[update.table];
        table.forEach(item => {
            if (update.chi_so_thanh_phan === 'a' && item.chi_so_thanh_phan_a === update.ten_chi_so) {
                item.gia_tri_thanh_phan_a = update.gia_tri;
            } else if (update.chi_so_thanh_phan === 'b' && item.chi_so_thanh_phan_b === update.ten_chi_so) {
                item.gia_tri_thanh_phan_b = update.gia_tri;
            }
            calculate_gia_tri_tham_chieu(frm, item);
        });
    });
}

function calculate_gia_tri_tham_chieu(frm, item) {
    let gia_tri_a = parseFloat(item.gia_tri_thanh_phan_a) || 0;
    let gia_tri_b = parseFloat(item.gia_tri_thanh_phan_b) || 0;
    if (gia_tri_a !== 0 && gia_tri_b !== 0) {
        item.gia_tri_tham_chieu = (gia_tri_a / gia_tri_b) * 100;
    } else if (item.gia_tri_tham_chieu === null || item.gia_tri_tham_chieu === undefined) {
        // Fetch gia_tri_tham_chieu from index_table if not both
        const indexTableItem = frm.doc.gso_input_index_table.find(row => row.ten_chi_so === item.ten_chi_so);
        if (indexTableItem) {
            item.gia_tri_tham_chieu = indexTableItem.gia_tri;
        } else {
            item.gia_tri_tham_chieu = null;
        }
    }
}

function refreshFields(frm) {
    const fieldsToRefresh = [
        'bang_nhan_thuc_so_va_the_che_so',
        'bang_ha_tang_va_an_ninh_mang',
        'bang_nhan_luc_so',
        'bang_hoat_dong_kinh_te_so',
        'bang_kts_logistics',
        'bang_doanh_thu_nganh_kts'
    ];

    fieldsToRefresh.forEach(field => {
        frm.refresh_field(field);
    });
}
